#include "rinkfit/augmented_lagrangian.hpp"
#include "rinkfit/event_io.hpp"
#include <fstream>
#include <iostream>
using namespace rinkfit;
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("CURRENT_COMPLETE_CP DONOR_SAME_SCOPE_CP DONOR_MODEL NEW_OUT");const std::filesystem::path out=argv[4];if(std::filesystem::exists(out))throw std::runtime_error("immutable numerical primal proposal exists");std::ifstream cf(argv[1]),df(argv[2]);auto current=read_checkpoint(cf);auto donor=read_checkpoint(df);if(!(current.state.data().identity==donor.state.data().identity)||current.state.data().parameters.size()!=donor.state.data().parameters.size()||current.state.data().discrete!=donor.state.data().discrete||current.state.data().root_charts!=donor.state.data().root_charts)throw std::runtime_error("donor is not the identical original physical/source/finite problem");auto payload=current.state.data();std::size_t changed=0;bool budget=false;for(std::size_t i=0;i<payload.parameters.size();++i){auto&a=payload.parameters[i];const auto&d=donor.state.data().parameters[i];if(a.name!=d.name||a.equality_auxiliary!=d.equality_auxiliary||a.values.size()!=d.values.size())throw std::runtime_error("donor named primal layout mismatch");if(a.name=="budget_sq"){budget=true;continue;}if(a.values!=d.values)++changed;a.values=d.values;}if(!budget)throw std::runtime_error("missing exact current budget");const auto current_token=current.state.token();current.state=StateSnapshot(std::move(payload));std::filesystem::create_directories(out);{std::ofstream f(out/"resume_checkpoint.json");write_checkpoint(f,current);}std::filesystem::copy_file(argv[3],out/"model.json");eventio::atomic_json(out/"receipt.json",{{"schema","rinkfit.same_problem_donor_primal_with_current_complete_AL_metadata_numerical_proposal.v1"},{"current_checkpoint_sha256",eventio::file_sha256(argv[1])},{"donor_checkpoint_sha256",eventio::file_sha256(argv[2])},{"donor_model_sha256",eventio::file_sha256(argv[3])},{"current_state_token",current_token},{"state_token",current.state.token()},{"changed_named_primal_blocks",changed},{"current_budget_duals_rho_phase_outer_attempt_elapsed_runtime_and_finite_discrete_preserved",true},{"candidate_not_accepted_before_complete_original_AL_test",true},{"source_or_domain_or_measurement_identity_changed",false},{"checkpoint_sha256",eventio::file_sha256(out/"resume_checkpoint.json")}});std::cout<<"numerical primal candidate prepared; current AL metadata and budget preserved";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
